command.text:
cat > spec.json << 'EOF'
{
  "predictors": {
    "option": "every_outcome",
    "covariate_periods": [1, 40]
  },
  "v": {
    "option": "pre_period_fit"
  },
  "weights": {
    "option": "convex"
  },
  "penalty": {
    "option": "none"
  }
}
EOF
Rscript scripts/fit.R spec.json > fit_output.txt
head -n 20 fit_output.txt

awk 'NR>=41 && NR<=60 {obs=$2; synth=$3; gap=$4; sum_gap+=gap; cnt+=1; cf[NR]=synth} END {printf "ATT=%.6f\n", sum_gap/cnt}' fit_output.txt > att.txt
awk 'NR>=41 && NR<=60 {printf "\"%d\": %.6f,\n", NR, cf[NR]}' fit_output.txt > cf.json
# Build answer.json
cat > answer.json <<EOF
{
  "counterfactual": {
$(cat cf.json | sed '$ s/,$//')
  },
  "att": $(cat att.txt | cut -d= -f2),
  "rationale": "Used every pre‑treatment outcome as predictors, V chosen to fit pre‑period outcomes, convex donor weights, no penalty. This simple design lets the synthetic control closely match the treated unit before period 41, providing a reasonable counterfactual for periods 41‑60."
}
EOF
cat answer.json

